"""Optional diagnostic extension, applied only to copied gameplay helpers.
No production renderer hooks or game logic changes. Exact supported client only.
"""
RUNNER_CHANGES=[('from effect_observer import actor_effects', 'from effect_observer import actor_effects\nfrom visual_observer import visual_state, verify_renderer'), ("mode in ('filter-save','filter-restore') and 'client.dll'", "(mode in ('filter-save','filter-restore') or mode.startswith('native-hunger')) and 'client.dll'"), ("dump(session/'native_compat.json',dep);checked_compat=True", "dump(session/'native_compat.json',dep);checked_compat=True\n                                dump(session/'visual_native.json',verify_renderer(reader,path('game')))"), ("detail['snapshot_request']=snapshot_request", "detail['visual']=visual_state(reader)\n                            detail['snapshot_request']=snapshot_request"), ('deadline=time.monotonic()+(150 if', "deadline=time.monotonic()+(90 if mode.startswith('native-hunger') else 150 if")]
PROBE_EXTRA="\n# Test-only: native visual state and real unmodified render output.\n_base_mark=mark\ndef mark(label):\n    _base_mark(label)\n    if label in ['NATIVE_HUNGER_BEFORE','NATIVE_HUNGER_SETTLED','NATIVE_HUNGER_AFTER_CALLBACK','FILTER_RETURN_SETTLED','FILTER_ALL_OFF']:\n        log(('VISUAL_SHOT',label));command('snapshot')\ndef filter_audit_return():\n    mark('FILTER_RETURN_SETTLED');command('p5_end');later(3.,'filter_audit_off()')\ndef filter_audit_off():\n    mark('FILTER_ALL_OFF');later(.5,'finish()')\n"
AUDIT_EXTRA="\n_base_audit=audit\ndef audit(mode,log,rows):\n checks=_base_audit(mode,log,rows)\n if not mode.startswith('native-hunger'):return checks\n events=[ast.literal_eval(line) for line in log.splitlines()]\n d={e[1]:e[2] for e in events if e[0]=='NATIVE'}\n keys=['NATIVE_HUNGER_BEFORE','NATIVE_HUNGER_SETTLED','NATIVE_HUNGER_AFTER_CALLBACK','FILTER_RETURN_SETTLED','FILTER_ALL_OFF']\n v={key:d[key]['visual'] for key in keys}\n parameters=['intensity','blur_radius','expand','dx6']\n for key in keys:\n  assert all(v[key][p]==v[keys[0]][p] for p in parameters),('Visual parameters changed',key,v)\n  assert v[key]['feedvision']['float']==0,('Additional feeding overlay',key,v[key])\n  assert len(v[key]['raw_protean'])==1,v[key]\n def red(q):return q['raw_protean'][0]>=1 or q['health_ankh']>0 or q['redvision_flag']!=0\n assert red(v['NATIVE_HUNGER_SETTLED']) and red(v['NATIVE_HUNGER_AFTER_CALLBACK'])\n assert v['NATIVE_HUNGER_AFTER_CALLBACK']['health_ankh']<=v['NATIVE_HUNGER_SETTLED']['health_ankh']\n assert v['NATIVE_HUNGER_SETTLED']['mat_fullbright']==v['NATIVE_HUNGER_AFTER_CALLBACK']['mat_fullbright']\n assert not red(v['FILTER_ALL_OFF']) and v['FILTER_ALL_OFF']['mat_fullbright']['integer']==0\n if 'warform' in mode:\n  assert red(v['NATIVE_HUNGER_BEFORE']) and red(v['FILTER_RETURN_SETTLED']),v\n else:\n  assert not red(v['NATIVE_HUNGER_BEFORE']) and not red(v['FILTER_RETURN_SETTLED']),v\n  assert all(v[key]['mat_fullbright']['integer']==0 for key in keys),v\n return checks+['Fresh client visual state: stable RedVision parameters across double callback, no feeding overlay, unchanged brightness, correct natural-end/Protean-end cleanup']\n"

def stage(live):
    def change(text,old,new):
        assert text.count(old)==1,('Gameplay helper interface changed',old)
        return text.replace(old,new,1)
    path=live/'run_game.py';text=path.read_text()
    for old,new in RUNNER_CHANGES:text=change(text,old,new)
    path.write_text(text)
    path=live/'game_probe.py';text=path.read_text()
    text=change(text,"mark('NATIVE_HUNGER_MOVED');command('p5_end');later(2.5,'finish()')","mark('NATIVE_HUNGER_MOVED');later(.8,'filter_audit_return()')")
    path.write_text(text+PROBE_EXTRA)
    path=live/'audit_game.py';path.write_text(path.read_text()+AUDIT_EXTRA)
